H,W=28,19
g=[[0]*W for _ in range(H)]
objs={
2:[(0,14),(1,14),(2,14),(2,15),(2,16),(3,14),(4,14)],
7:[(0,0),(1,1),(1,2),(1,3),(2,1),(2,2),(2,3),(3,1),(3,2),(3,3),(4,4)],
3:[(0,0),(0,1),(1,0),(2,0),(3,0)],
