# place 2 top col14; 7 bottom with min col10, bbox height5; 3 bottom at min col17 bbox h4; 8 bottom min col3 bbox h3
for color,shape in objs.items():
    if color==2: rbase,cbase=0,14
    elif color==7: rbase,cbase=23,10
    elif color==3: rbase,cbase=24,17
    else: rbase,cbase=25,3
    for dr,dc in shape:
        rr,cc=rbase+dr,cbase+dc
        if not (0<=rr<H and 0<=cc<W): print('bad')
        if g[rr][cc]!=0: print('overlap',color,rr,cc)
        g[rr][cc]=color
import json
print(json.dumps(g))

